from pathlib import Path

# The Issue #13 unit test is generated by apply-issue13.py. It must inspect only
# customer-facing field text; internal field keys and stable route IDs may keep
# historical English identifiers.
path = Path("tests/issue-13.test.ts")
text = path.read_text(encoding="utf-8")
old = '    expect(JSON.stringify(GAS_FIELDS)).not.toMatch(/recovery/i);'
new = '''    const publicFieldText = Object.values(GAS_FIELDS)\n      .flat()\n      .flatMap((field) => [field.label, field.help ?? ""])\n      .join(" ");\n    expect(publicFieldText).not.toMatch(/\\brecovery\\b/i);'''
if text.count(old) != 1:
    raise RuntimeError(f"Expected exactly one public-copy assertion, found {text.count(old)}")
path.write_text(text.replace(old, new, 1), encoding="utf-8")

# Existing acceptance tests encode the previous approved copy. Issue #13 changes
# that public contract deliberately, so update only those exact expectations.
replacements = [
    ("Компрессоры и бустеры для технологических газов", "Безмасляные компрессоры и бустеры для технологических газов"),
    ("Свежий газ или recovery?", "Источник гелия"),
    ("/Подобрать компрессор для N₂/", "/Подобрать компрессор для азота/"),
]
for test_path in Path("tests").rglob("*.ts"):
    current = test_path.read_text(encoding="utf-8")
    updated = current
    for before, after in replacements:
        updated = updated.replace(before, after)
    if updated != current:
        test_path.write_text(updated, encoding="utf-8")
